/* @lc app=leetcode id=3395 lang=kotlin */ class Solution { fun c2(x: Long): Long = x * (x - 1) / 2 fun c(n: Long, k: Int): Long = if (k == 0) 1L else if (k == 1) n else c2(n) fun subsequencesWithMiddleMode(nums: IntArray): Int = 1_000_000_007L.let { M -> nums.toSortedSet().toList().let { u -> nums.map { u.binarySearch(it) }.let { r -> u.size.let { m -> IntArray(m).also { rc -> r.forEach { rc[it]++ } }.let { rc -> IntArray(m).let { lc -> r.indices.fold(0L) { acc, i -> r[i].let { v -> rc[v]--.let { _ -> lc[v].toLong().let { cl -> rc[v].toLong().let { cr -> (i - cl).let { lnv -> (nums.size - 1 - i - cr).let { rnv -> (0 until m).filter { it != v }.let { os -> (lnv * c2(rnv) - lnv * os.sumOf { c2(rc[it].toLong()) } - os.sumOf { lc[it].toLong() * rc[it] * (rnv - rc[it]) }).let { g1 -> (rnv * c2(lnv) - rnv * os.sumOf { c2(lc[it].toLong()) } - os.sumOf { rc[it].toLong() * lc[it] * (lnv - lc[it]) }).let { g2 -> ((0..2).sumOf { a -> (0..2).filter { b -> a + b >= 2 }.sumOf { b -> c(cl, a) % M * (c(lnv, 2 - a) % M) % M * (c(cr, b) % M) % M * (c(rnv, 2 - b) % M) % M } } + cl * g1 + cr * g2).let { tot -> lc[v]++.let { (acc + tot % M + M) % M } } } } } } } } } } } } }.toInt() } } } } } }